<script>
var DEFAULT_STAT = {
  "日期": "", "星期": "", "时间": "",
  "玩家": { "当前位置": "", "飞机杯当前绑定": "无", "飞机杯定位": "未知",
            "体力": 100, "性欲": 30, "勃起度": 0, "累计射精次数": 0 },
  "女性角色": {}, "男性角色": {}
};

var qiuOpenCards = {};

function safe(v, def) { return (v === undefined || v === null || v === '') ? (def || '—') : v; }
function safeNum(v, def) { var n = Number(v); return isNaN(n) ? (def || 0) : n; }

function deepMergeStat(target, source) {
  if (source === null || source === undefined) return target;
  if (typeof source !== 'object' || Array.isArray(source)) return source;
  if (typeof target !== 'object' || target === null) target = {};
  for (var k in source) {
    if (!source.hasOwnProperty(k)) continue;
    if (typeof source[k] === 'object' && source[k] !== null && !Array.isArray(source[k])) {
      target[k] = deepMergeStat(target[k] || {}, source[k]);
    } else {
      target[k] = source[k];
    }
  }
  return target;
}

// ===== 多源读取机制（参照同级生2 状态栏模式） =====
var TH_HOSTS = [window, window.parent, window.top].filter(function(w, i, arr) {
  return w && arr.indexOf(w) === i;
});

function pickHostFn(name) {
  if (typeof window[name] === 'function') return function() { return window[name].apply(window, arguments); };
  for (var i = 0; i < TH_HOSTS.length; i++) {
    try {
      var h = TH_HOSTS[i];
      if (typeof h[name] === 'function') {
        return (function(host, n) { return function() { return host[n].apply(host, arguments); }; })(h, name);
      }
    } catch(e) {}
  }
  return null;
}

function pickHostValue(name) {
  if (window[name] !== undefined) return window[name];
  for (var i = 0; i < TH_HOSTS.length; i++) {
    try { if (TH_HOSTS[i][name] !== undefined) return TH_HOSTS[i][name]; } catch(e) {}
  }
  return undefined;
}

function getMvu() { return pickHostValue('Mvu') || window.Mvu || null; }

function parseEmbeddedStat() {
  var el = document.getElementById('mvu-stat-embed');
  if (!el) return null;
  var raw = (el.textContent || el.innerText || '').trim();
  if (!raw || raw.indexOf('format_message_variable') >= 0) return null;
  try {
    var parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object') {
      if (parsed.stat_data && typeof parsed.stat_data === 'object') return parsed.stat_data;
      return parsed;
    }
  } catch(e) {}
  return null;
}

function hasMeaningfulStatData(stat) {
  return stat && typeof stat === 'object' && !Array.isArray(stat) && Object.keys(stat).length > 0;
}

function pickStatData(source){if(!source||typeof source!=='object')return null;var stat=source.stat_data;return hasMeaningfulStatData(stat)?stat:null}

function resolveMessageIdFromDom() {
  try {
    var frame = window.frameElement;
    if (frame && frame.closest) {
      var mes = frame.closest('.mes');
      if (mes) {
        var id = parseInt(mes.getAttribute('mesid'), 10);
        if (id >= 0) return id;
      }
    }
    var el = frame;
    while (el) {
      if (el.classList && el.classList.contains('mes')) {
        var id2 = parseInt(el.getAttribute('mesid'), 10);
        if (id2 >= 0) return id2;
      }
      el = el.parentElement;
    }
    for (var i = 0; i < TH_HOSTS.length; i++) {
      try {
        var host = TH_HOSTS[i];
        var host$ = host.$ || host.jQuery;
        if (!host$ || !frame) continue;
        var $mes = host$(frame).closest('.mes');
        if ($mes && $mes.length) {
          var id3 = parseInt($mes.attr('mesid'), 10);
          if (id3 >= 0) return id3;
        }
      } catch(e) {}
    }
  } catch(e) {}
  return -1;
}

function resolveMessageIdFromIframeName() {
  var fn = pickHostFn('getIframeName');
  if (!fn) return -1;
  try {
    var name = String(fn() || '');
    var m = /^TH-message--(\d+)--/.exec(name);
    if (m) return parseInt(m[1], 10);
  } catch(e) {}
  return -1;
}

function resolveMessageId() {
  // 顺序必须与同级生2 一致: DOM > iframeName > window.message_id > getCurrentMessageId
  // 注意: getCurrentMessageId 可能返回主模型消息ID(非最新),不能放第一位
  var fromDom = resolveMessageIdFromDom();
  if (fromDom >= 0) return fromDom;
  var fromName = resolveMessageIdFromIframeName();
  if (fromName >= 0) return fromName;
  if (typeof window.message_id === 'number' && window.message_id >= 0) return window.message_id;
  try {
    var fn = pickHostFn('getCurrentMessageId');
    if (fn) {
      var id = fn();
      if (typeof id === 'number' && id >= 0) return id;
    }
  } catch(e) {}
  return -1;
}

function getMessageOption() {
  var messageId = resolveMessageId();
  return { type: 'message', message_id: messageId >= 0 ? messageId : 'latest' };
}

var cachedStatFromBridge = null;
var cachedBridgeMessageId = -1;

/* 同步降级读取：仅用于初始化快速渲染（数据可能滞后）
   根因修复：原 readStat 同步调用 Mvu.getMvuData() 返回的是 Promise，
   pickStatData(Promise) 返回 null，导致降级到 embed 旧快照。
   参考暗黑地牢生产级实现，拆分为 sync(快速降级) + async(真实读取) */
function readStatSync() {
  // 优先级1: embed 块（主模型消息内嵌的快照，初始化时最快可用）
  var embedded = parseEmbeddedStat();
  if (embedded) return deepMergeStat(DEFAULT_STAT, embedded);
  // 优先级2: bridge 缓存
  if (cachedStatFromBridge && hasMeaningfulStatData(cachedStatFromBridge)) {
    return deepMergeStat(DEFAULT_STAT, cachedStatFromBridge);
  }
  // 优先级3: DEFAULT_STAT
  return deepMergeStat(DEFAULT_STAT, {});
}

/* 异步读取：参考暗黑地牢生产级实现
   用 getLastMessageId 遍历最近消息，找最后一条 assistant 消息，
   用 await Mvu.getMvuData({type:'message', message_id}) 获取真实数据 */
async function readStatAsync() {
  try {
    if (typeof getLastMessageId === 'function') {
      var maxId = getLastMessageId();
      var Mvu = getMvu();
      var gv = pickHostFn('getVariables');
      for (var i = 0; i < 15; i++) {
        var cid = maxId - i;
        if (cid < 0) break;
        var msg = null;
        try { msg = getChatMessages(cid); } catch(e) { continue; }
        if (Array.isArray(msg)) msg = msg[0];
        if (!msg || msg.role !== 'assistant') continue;
        var mid = msg.message_id;
        if (typeof mid !== 'number' || mid < 0) continue;
        var v = null;
        try {
          if (Mvu && typeof Mvu.getMvuData === 'function') {
            v = await Mvu.getMvuData({type: 'message', message_id: mid});
          } else if (gv) {
            v = await gv({type: 'message', message_id: mid});
          }
        } catch(e) {}
        var stat = pickStatData(v);
        if (stat && hasMeaningfulStatData(stat)) {
          return deepMergeStat(DEFAULT_STAT, stat);
        }
      }
    }
  } catch(e) {}
  // 降级1: embed 快照
  var embedded = parseEmbeddedStat();
  if (embedded) return deepMergeStat(DEFAULT_STAT, embedded);
  // 降级2: bridge 缓存
  if (cachedStatFromBridge && hasMeaningfulStatData(cachedStatFromBridge)) {
    return deepMergeStat(DEFAULT_STAT, cachedStatFromBridge);
  }
  // 降级3: DEFAULT_STAT
  return deepMergeStat(DEFAULT_STAT, {});
}

function requestStatFromBridge() {
  var mesId = resolveMessageId();
  var payload = { type: 'fjb-mvu-stat-request', messageId: mesId };
  for (var i = 0; i < TH_HOSTS.length; i++) {
    try { TH_HOSTS[i].postMessage(payload, '*'); } catch(e) {}
  }
}

function waitForReadableStat(timeoutMs, cb) {
  timeoutMs = timeoutMs || 8000;
  var started = Date.now();
  (function poll() {
    var stat = readStatSync();
    if (hasMeaningfulStatData(stat)) { cb(stat); return; }
    requestStatFromBridge();
    if (Date.now() - started < timeoutMs) {
      setTimeout(poll, 180);
    } else {
      cb(readStat());
    }
  })();
}

function bar(value, max, cls) {
  var v = safeNum(value, 0);
  var pct = max > 0 ? Math.min(100, (v / max) * 100) : 0;
  return '<div class="qiu-bar-container"><div class="qiu-bar-track"><div class="qiu-bar-fill ' + (cls||'') + '" style="width:' + pct + '%"></div></div></div>';
}

function progressRow(name, value, max, phase, cls) {
  return '<div class="qiu-bar-container">' +
    '<div class="qiu-bar-top"><span class="qiu-progress-name">' + name + '</span><span>' + safeNum(value,0) + '/' + max + (phase ? ' · ' + phase : '') + '</span></div>' +
    '<div class="qiu-bar-track"><div class="qiu-bar-fill ' + (cls||'') + '" style="width:' + (max > 0 ? Math.min(100, (safeNum(value,0)/max)*100) : 0) + '%"></div></div>' +
  '</div>';
}

function phaseName(val, thresholds) {
  var v = safeNum(val, 0);
  for (var i = 0; i < thresholds.length; i++) {
    if (v <= thresholds[i].max) return thresholds[i].name;
  }
  return thresholds[thresholds.length-1].name;
}

