function bindCardToggle() {
  var headers = document.querySelectorAll('.qiu-card-header');
  for (var i = 0; i < headers.length; i++) {
    headers[i].onclick = function() {
      var card = this.parentNode;
      if (card && card.className.indexOf('qiu-char-card') !== -1) {
        var nameEl = this.querySelector('.qiu-char-name');
        var cardName = nameEl ? nameEl.textContent : '';
        if (card.className.indexOf('is-open') !== -1) {
          card.className = card.className.replace(/\s*is-open\s*/, ' ').trim();
          if (cardName) delete qiuOpenCards[cardName];
        } else {
          card.className = (card.className + ' is-open').trim();
          if (cardName) qiuOpenCards[cardName] = true;
        }
      }
    };
  }
}

function restoreOpenState() {
  var cards = document.querySelectorAll('.qiu-char-card');
  for (var i = 0; i < cards.length; i++) {
    var nameEl = cards[i].querySelector('.qiu-char-name');
    if (!nameEl) continue;
    var name = nameEl.textContent;
    if (qiuOpenCards[name]) {
      cards[i].className = (cards[i].className + ' is-open').trim();
    }
  }
}

function populateCharacterData() {
  try {
  var stat = readStatSync();

  document.getElementById('qiu-datetime').textContent = safe(stat.日期) + ' ' + safe(stat.时间);
  document.getElementById('qiu-weekday').textContent = safe(stat.星期);
  document.getElementById('qiu-location').textContent = safe(stat.玩家 && stat.玩家.当前位置);
  document.getElementById('qiu-cup-bind').textContent = safe(stat.玩家 && stat.玩家.飞机杯当前绑定, '无');
  document.getElementById('qiu-cup-loc').textContent = safe(stat.玩家 && stat.玩家.飞机杯定位, '未知');

  var bindBox = document.getElementById('qiu-cup-bind-box');
  var bindName = stat.玩家 && stat.玩家.飞机杯当前绑定;
  if (bindName && bindName !== '无') {
    bindBox.className = 'qiu-env-box bind-active';
  } else {
    bindBox.className = 'qiu-env-box';
  }

  var playerBox = document.getElementById('qiu-player-box');
  playerBox.innerHTML = renderPlayer(stat);

  var femaleContainer = document.getElementById('qiu-female-chars');
  var females = stat.女性角色 || {};
  var femaleNames = Object.keys(females);
  // DEBUG: 诊断女性角色读取
  try {
    var debugInfo = '[DEBUG] stat.女性角色 type: ' + typeof stat.女性角色 + ' | keys: ' + JSON.stringify(femaleNames) + ' | length: ' + femaleNames.length;
    console.log(debugInfo);
    if (femaleNames.length > 0) {
      var firstFemale = females[femaleNames[0]];
      console.log('[DEBUG] 第一个女性角色:', femaleNames[0], '字段数:', Object.keys(firstFemale || {}).length);
      console.log('[DEBUG] 生理状态:', JSON.stringify(firstFemale?.生理状态).substring(0, 200));
    }
  } catch(e) { console.error('[DEBUG] 诊断错误:', e); }
  if (femaleNames.length === 0) {
    femaleContainer.innerHTML = '<div class="qiu-empty-hint">暂无已追踪女性角色 (调试: ' + typeof stat.女性角色 + ')</div>';
  } else {
    var fhtml = '';
    var bindNameLower = bindName;
    for (var i = 0; i < femaleNames.length; i++) {
      var n = femaleNames[i];
      fhtml += renderFemale(n, females[n], n === bindNameLower, stat);
    }
    femaleContainer.innerHTML = fhtml;
  }

  var maleContainer = document.getElementById('qiu-male-chars');
  var males = stat.男性角色 || {};
  var maleNames = Object.keys(males);
  if (maleNames.length === 0) {
    maleContainer.innerHTML = '<div class="qiu-empty-hint">暂无男性角色</div>';
  } else {
    var mhtml = '';
    for (var j = 0; j < maleNames.length; j++) {
      mhtml += renderMale(maleNames[j], males[maleNames[j]]);
    }
    maleContainer.innerHTML = mhtml;
  }

  bindCardToggle();
  restoreOpenState();
  } catch(e) {
    console.error('[qiu-populateCharacterData] ERROR:', e.message, e.stack);
    var fc = document.getElementById('qiu-female-chars');
    if (fc) fc.innerHTML = '<div class="qiu-empty-hint">渲染异常: '+e.message+'</div>';
  }
}

function autoRefresh() {
  setTimeout(function() {
    populateCharacterData();
    // 如果首次读取不到数据，启动 bridge 请求 + 等待机制
    waitForReadableStat(8000, function(realStat) {
      if (hasMeaningfulStatData(realStat)) {
        populateCharacterData();
      }
    });
  }, 800);
}

function setupEventListeners() {
  // 根据 DB C1: 用 eventOn 监听事件(TH 注入的全局函数)
  try {
    if (typeof eventOn === 'function') {
      // iframe 内事件
      try {
        if (typeof iframe_events !== 'undefined' && iframe_events.GENERATION_ENDED) {
          eventOn(iframe_events.GENERATION_ENDED, autoRefresh);
        } else {
          eventOn('js_generation_ended', autoRefresh);
        }
      } catch(e) {}
      try {
        if (typeof iframe_events !== 'undefined' && iframe_events.MESSAGE_IFRAME_RENDER_ENDED) {
          eventOn(iframe_events.MESSAGE_IFRAME_RENDER_ENDED, autoRefresh);
        }
      } catch(e) {}
      // tavern_events
      try {
        if (typeof tavern_events !== 'undefined') {
          if (tavern_events.MESSAGE_UPDATED) eventOn(tavern_events.MESSAGE_UPDATED, autoRefresh);
          if (tavern_events.MESSAGE_EDITED) eventOn(tavern_events.MESSAGE_EDITED, autoRefresh);
          if (tavern_events.CHARACTER_MESSAGE_RENDERED) eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, autoRefresh);
        }
      } catch(e) {}
    }
  } catch(e) {}

    // 参考同级生2 生产级: 直接用字符串事件名,不需要 waitGlobalInitialized
  try {
    if (typeof eventOn === 'function') {
      eventOn('mag_variable_update_ended', autoRefresh);
    }
  } catch(e) {}
  // MVU 事件枚举（兼容，Mvu 可能已就绪）
  try {
    var MvuEvt = getMvu();
    if (MvuEvt && MvuEvt.events && MvuEvt.events.VARIABLE_UPDATE_ENDED && typeof eventOn === 'function') {
      eventOn(MvuEvt.events.VARIABLE_UPDATE_ENDED, autoRefresh);
    }
    if (MvuEvt && MvuEvt.events && MvuEvt.events.VARIABLE_INITIALIZED && typeof eventOn === 'function') {
      eventOn(MvuEvt.events.VARIABLE_INITIALIZED, autoRefresh);
    }
  } catch(e) {}


  // 监听父窗口推送的 bridge 数据
  window.addEventListener('message', function(e) {
    try {
      var data = e.data;
      if (data && data.type === 'fjb-mvu-stat-data' && data.stat_data) {
        var mesId = resolveMessageId();
        if (mesId >= 0 && typeof data.messageId === 'number' && data.messageId >= 0 && data.messageId !== mesId) return;
        if (hasMeaningfulStatData(data.stat_data)) {
          cachedStatFromBridge = data.stat_data;
          cachedBridgeMessageId = typeof data.messageId === 'number' ? data.messageId : mesId;
          populateCharacterData();
        }
      }
    } catch(err) {}
  });
}

/* refresh - 异步版本，参考同级生2/暗黑地牢生产级实现 */
async function refresh() {
  if (window._qiu_refreshing) return;
  window._qiu_refreshing = true;
  /* 第一步：用 embed 快照快速渲染一次（避免界面空白） */
  populateCharacterData();
  /* 第二步：异步获取最新 MVU 数据 */
  try {
    var realStat = await readStatAsync();
    if (hasMeaningfulStatData(realStat)) {
      // 临时把数据塞进 cachedStatFromBridge，让 populateCharacterData 读到
      cachedStatFromBridge = realStat;
      populateCharacterData();
    }
  } catch(e) {}
  window._qiu_refreshing = false;
  requestStatFromBridge();
}

/* 初始化 - IIFE 同步模式（参考同级生2 生产级） */
(function init() {
  populateCharacterData();
  setupEventListeners();
  // 立即触发一次异步刷新
  refresh();
  // 监听窗口 message（bridge 数据回传）
  window.addEventListener('message', function(e) {
    try {
      var data = e.data;
      if (data && data.type === 'fjb-mvu-stat-data' && data.stat_data) {
        if (hasMeaningfulStatData(data.stat_data)) {
          cachedStatFromBridge = data.stat_data;
          cachedBridgeMessageId = typeof data.messageId === 'number' ? data.messageId : resolveMessageId();
          populateCharacterData();
        }
      }
    } catch(x) {}
  });
  // 定时兜底刷新（10秒）
  setInterval(function() { refresh(); }, 10000);
})();
</script>
