// 飞机杯状态栏 bridge 脚本
// 监听 iframe 的 stat_data 请求，从 MVU 读取最新数据并推送回 iframe
(function() {
  if (window.__fjb_bridge_installed) return;
  window.__fjb_bridge_installed = true;

  function getStatDataForMessage(messageId) {
    var opt = { type: 'message', message_id: messageId >= 0 ? messageId : 'latest' };
    try {
      if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
        var data = Mvu.getMvuData(opt);
        if (data && data.stat_data) return data.stat_data;
        if (data) return data;
      }
    } catch(e) {}
    try {
      if (typeof getVariables === 'function') {
        var vars = getVariables(opt);
        if (vars && vars.stat_data) return vars.stat_data;
      }
    } catch(e) {}
    try {
      if (typeof getVariables === 'function') {
        var vars2 = getVariables({ type: 'chat' });
        if (vars2 && vars2.stat_data) return vars2.stat_data;
      }
    } catch(e) {}
    return null;
  }

  window.addEventListener('message', function(e) {
    try {
      var data = e.data;
      if (!data || data.type !== 'fjb-mvu-stat-request') return;
      var messageId = typeof data.messageId === 'number' ? data.messageId : -1;
      var stat = getStatDataForMessage(messageId);
      if (stat) {
        e.source.postMessage({
          type: 'fjb-mvu-stat-data',
          messageId: messageId,
          stat_data: stat
        }, '*');
      }
    } catch(err) {}
  });

  // MVU 变量更新完成后，主动向所有 iframe 推送最新数据
  try {
    if (typeof eventOn === 'function') {
      eventOn('mag_variable_update_ended', function() {
        try {
          var iframes = document.querySelectorAll('iframe');
          for (var i = 0; i < iframes.length; i++) {
            var frame = iframes[i];
            try {
              var stat = getStatDataForMessage(-1);
              if (stat) {
                frame.contentWindow.postMessage({
                  type: 'fjb-mvu-stat-data',
                  messageId: -1,
                  stat_data: stat
                }, '*');
              }
            } catch(err) {}
          }
        } catch(err) {}
      });
    }
  } catch(e) {}
})();

